(The Hurewicz map) \label{hurewicz} Let $(X,d)$ be a proper metric space and $n\in \mathbb{N}_{0}$. There is a natural morphism 
\begin{align*}
\mathcal{H}: \pi_{n}^{c}(X)\rightarrow H\mathcal{X}_{n+1}(X)
\end{align*}
such that the diagram 


\begin{figure}[H]
\centering
\begin{tikzcd}
&\pi_{n}^{c}(X) \arrow{r}{\mathcal{H}} \arrow{d}{\cong}
&H\mathcal{X}_{n+1}(X)  \arrow{d}{\mathcal{A}}
  \\
&\varinjlim_{h\in \mathbb{N}} \pi^{e}_{n}(|\mathcal{U}_{h}|) \arrow{r}{\varphi}
&\varinjlim_{h\in \mathbb{N}} H^{lf}_{n+1}(|\mathcal{U}_{h}|) 
\end{tikzcd}
\end{figure}
commutes.

\label{conj:E2-equiv}
The $\EE_2$-monoidal category $\mathcal{B}_{\CS}^{(k)}$ obtained from BV-BFV quantization of Chern--Simons theory at level $k$ with gauge group $G$ is equivalent, as an $\EE_2$-category, to the ribbon category $\overline{\Rep}_q(G)$ at $q = e^{i\pi/(k+h^\vee)}$:
\begin{equation}
\mathcal{B}_{\CS}^{(k)} \;\simeq_{\EE_2}\; \overline{\Rep}_q(G).
\end{equation}

\label{conj: stationary measures}
    For given $\alpha \in \R_{>0}$ and $\beta, t \in \R$ with $\alpha>t>0$ and $\beta > -t$, $\{\mathcal{T}_{\beta, t}\}$ constitutes all extremal stationary measures for \eqref{def:recurrence}. For any initial data $Z(x,1)$ such that $\lim_{x\rightarrow \infty} \log Z(x,1)/x = -d \in \R$, we have the following. Let
    \begin{equation}\label{eq: relation}
     t = \alpha - \psi^{-1}(d).        
    \end{equation}
    \begin{itemize}
        \item(High density) For $\beta \geq -t$ and $t \geq 0,$ the process $\left(Z(x+N, N) / Z(N,N)\right)_{x\in \Z_{\geq 0}}$ converges weakly as $N \rightarrow \infty$ to $(\mathcal{T}_{\beta,t}(x))_{x\in \Z_{\geq 0}}$.
        \item(Maximal current) For $\beta \geq 0$ and $t \leq 0$, the process $\left(Z(x+N, N)/Z(N,N)\right)_{x\in \Z_{\geq 0}}$ 
        converges weakly as $N \rightarrow \infty$ to $(\mathcal{T}_{\beta,0}(x))_{x\in \Z_{\geq0}}$.
        \item(Low density) For $-t \geq \beta$ and $\beta \leq 0,$ the process $\left(Z(x+N, N)/ Z(N,N)\right)_{x\in \Z_{\geq 0}}$ converges weakly as $N \rightarrow \infty$ to $(\mathcal{T}_{-t,t}(x))_{x\in \Z_{\geq 0}}$, i.e., a $\Gamm(\alpha + t)$ multiplicative random walk.
    \end{itemize}

